var ITEMS=[["What tailors do","Tailors fit, alter, and construct garments: hemming, taking in, letting out, and building bespoke suits. Great tailoring is invisible \u2014 the garment simply fits. Alterations are the steady business; bespoke is the art."], ["Essential tools","Quality shears, seam ripper, measuring tape, tailor's chalk, pins and pincushion, hand needles, thimble, iron and pressing ham, sleeve board, and a dress form. Machine: a reliable straight-stitch plus serger."], ["Key skills","Measuring accurately: the foundation of everything. Hand stitching: fell, slip, and pad stitches. Pressing: shaping with heat and steam. Fitting: reading wrinkles to diagnose fit. Pattern adjustment. Invisible repairs."], ["Safety essentials","Iron burns: the tailor's constant hazard. Needle safety: thimbles and care. Rotary cutter discipline: always away from the body, blade retracted. Ergonomics: cutting tables at proper height."], ["Getting started","Sew at home first, then apprentice with an alterations tailor \u2014 alterations teach fitting fast. Courses in pattern-making deepen skill. Build a portfolio of before/after fits."], ["Pro tips","Press every seam as you sew \u2014 pressing is half of tailoring. Fit on the body, not the form. Underpromise timelines in wedding season. Keep detailed client measurement cards."], ["Alteration","Trade term \u2014 Alteration: Adjusting a finished garment."], ["Bespoke","Trade term \u2014 Bespoke: Made from scratch to the individual."], ["Made to measure","Trade term \u2014 Made to measure: Adjusted standard patterns."], ["Hem","Trade term \u2014 Hem: The finished bottom edge."], ["Inseam","Trade term \u2014 Inseam: The inner leg seam measurement."], ["Take in","Trade term \u2014 Take in: Make smaller."], ["Let out","Trade term \u2014 Let out: Make larger using seam allowances."], ["Dart","Trade term \u2014 Dart: A stitched fold shaping fabric to the body."], ["Ease","Trade term \u2014 Ease: Extra fabric for movement."], ["Grain line","Trade term \u2014 Grain line: The fabric's lengthwise direction."], ["Bias","Trade term \u2014 Bias: The 45-degree diagonal with stretch."], ["Selvedge","Trade term \u2014 Selvedge: The finished fabric edge."], ["Interfacing","Trade term \u2014 Interfacing: Stiffening inside collars and cuffs."], ["Canvas","Trade term \u2014 Canvas: The chest interlining of a quality suit."], ["Felling","Trade term \u2014 Felling: Hand stitch holding hems invisibly."], ["Pad stitch","Trade term \u2014 Pad stitch: Hand stitch shaping lapels."], ["Topstitch","Trade term \u2014 Topstitch: Visible decorative stitching."], ["Basting","Trade term \u2014 Basting: Temporary long stitches for fitting."], ["Muslin/toile","Trade term \u2014 Muslin/toile: The test garment before cutting fashion fabric."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
